{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.AV_MASTER_HTMBASE AS WITH product_images AS ( SELECT sku_group, image_url FROM snitch_db.maplemonk.base_product ), metafields_std AS ( SELECT sku_group, product_name, CASE WHEN UPPER(category) LIKE \'%T-SHIRTS%\' THEN CASE WHEN UPPER(TRIM(designs)) = \'SOLID\' THEN \'Solid\' WHEN UPPER(TRIM(designs)) = \'GRAPHIC PRINT\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'TEXTURED\' THEN \'Textured\' WHEN UPPER(TRIM(designs)) = \'SELF DESIGN\' THEN \'Textured\' WHEN UPPER(TRIM(designs)) = \'STRIPES\' THEN \'Stripes\' WHEN UPPER(TRIM(designs)) = \'OTHERS\' THEN \'Others\' WHEN UPPER(TRIM(designs)) = \'PRINTED\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'EMBROIDED\' THEN \'Embroided\' WHEN UPPER(TRIM(designs)) = \'GEOMETRIC\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'CHECKS\' THEN \'Checks\' WHEN UPPER(TRIM(designs)) = \'FLORAL\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'TIE & DYE\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'EMBELLISHED\' THEN \'Embroided\' WHEN UPPER(TRIM(designs)) = \'ANIMAL PRINT\' THEN \'Graphic Print\' ELSE \'Others\' END WHEN UPPER(category) LIKE \'%SHIRTS%\' THEN CASE WHEN UPPER(TRIM(designs)) = \'SOLID\' THEN \'Solid\' WHEN UPPER(TRIM(designs)) = \'STRIPES\' THEN \'Stripes\' WHEN UPPER(TRIM(designs)) = \'TEXTURED\' THEN \'Textured\' WHEN UPPER(TRIM(designs)) = \'CHECKS\' THEN \'Checks\' WHEN UPPER(TRIM(designs)) = \'SELF DESIGN\' THEN \'Textured\' WHEN UPPER(TRIM(designs)) = \'PRINTED\' THEN \'Printed\' WHEN UPPER(TRIM(designs)) = \'OTHERS\' THEN \'Others\' WHEN UPPER(TRIM(designs)) = \'FLORAL\' THEN \'Printed\' WHEN UPPER(TRIM(designs)) = \'EMBROIDED\' THEN \'Embroided\' WHEN UPPER(TRIM(designs)) = \'GEOMETRIC\' THEN \'Printed\' WHEN UPPER(TRIM(designs)) = \'TIE & DYE\' THEN \'Printed\' WHEN UPPER(TRIM(designs)) = \'EMBELLISHED\' THEN \'Embroided\' WHEN UPPER(TRIM(designs)) = \'GRAPHIC PRINT\' THEN \'Printed\' WHEN UPPER(TRIM(designs)) = \'ANIMAL PRINT\' THEN \'Printed\' ELSE \'Other\' END ELSE designs END AS designs_new, CASE WHEN UPPER(category) LIKE \'%T-SHIRTS%\' THEN CASE WHEN TRIM(LOWER(collar_new)) IN (\'mock\',\'spread\',\'cuban\',\'mandarin\',\'baseball\',\'high neck\',\'zip\',\'others\') THEN \'Others\' WHEN TRIM(LOWER(collar_new)) IN (\'v neck\',\'crew\',\'round\') THEN \'Round\' WHEN TRIM(LOWER(collar_new)) = \'polo\' THEN \'Polo\' ELSE \'Others\' END ELSE collar_new END AS collar_new_modified, fit, CASE WHEN UPPER(sku_group) LIKE \'%4MLX%\' OR UPPER(sku_group) LIKE \'%4LRN%\' OR UPPER(sku_group) LIKE \'%4LPL%\' OR UPPER(sku_group) LIKE \'%4LTR%\' OR UPPER(sku_group) LIKE \'%4LCH%\' OR UPPER(sku_group) LIKE \'%4LJE%\' OR UPPER(sku_group) LIKE \'%4LJK%\' OR UPPER(sku_group) LIKE \'%4LSW%\' OR UPPER(sku_group) LIKE \'%4LHD%\' OR UPPER(sku_group) LIKE \'%4LOS%\' OR UPPER(sku_group) LIKE \'%4LSHS%\' OR UPPER(sku_group) LIKE \'%4LSFS%\' OR UPPER(sku_group) LIKE \'%4LSH%\' OR UPPER(sku_group) LIKE \'%4LBL%\' OR UPPER(sku_group) LIKE \'%4LCA%\' OR UPPER(sku_group) LIKE \'%4LSWT%\' OR UPPER(sku_group) LIKE \'%4LCD%\' OR UPPER(sku_group) LIKE \'%4LJO%\' THEN \'Luxe\' WHEN UPPER(sku_group) LIKE \'%4MBG%\' OR UPPER(sku_group) LIKE \'%4BRN%\' OR UPPER(sku_group) LIKE \'%4BPL%\' OR UPPER(sku_group) LIKE \'%4BTR%\' OR UPPER(sku_group) LIKE \'%4BCH%\' OR UPPER(sku_group) LIKE \'%4BJE%\' OR UPPER(sku_group) LIKE \'%4BJK%\' OR UPPER(sku_group) LIKE \'%4BSW%\' OR UPPER(sku_group) LIKE \'%4BHD%\' OR UPPER(sku_group) LIKE \'%4BOS%\' OR UPPER(sku_group) LIKE \'%4BSHS%\' OR UPPER(sku_group) LIKE \'%4BSFS%\' OR UPPER(sku_group) LIKE \'%4BSH%\' OR UPPER(sku_group) LIKE \'%4BBL%\' OR UPPER(sku_group) LIKE \'%4BCA%\' OR UPPER(sku_group) LIKE \'%4BSWT%\' OR UPPER(sku_group) LIKE \'%4BCD%\' OR UPPER(sku_group) LIKE \'%4BJO%\' THEN \'Plus\' ELSE \'Snitch\' END AS style, CASE WHEN TRIM(LOWER(sleeve_type)) IN (\'sleeveless\') THEN \'Sleeveless\' WHEN TRIM(LOWER(sleeve_type)) IN (\'half sleeve\',\'elbow sleeve\') THEN \'Half Sleeve\' WHEN TRIM(LOWER(sleeve_type)) IN (\'full sleeve\',\'three-quarter sleeves\') THEN \'Full Sleeve\' ELSE \'Others\' END AS sleeve_length, CASE WHEN LOWER(STYLE) LIKE \'%linen%\' THEN \'Linen\' WHEN MATERIAL_NEW = \'Cotton\' THEN \'Cotton\' WHEN MATERIAL_NEW IN (\'Tencel\', \'Tencil\', \'Polyester\', \'Terry\', \'Rayon\', \'Nylon\', \'Modal\', \'Others\') THEN \'Polyester\' WHEN MATERIAL_NEW = \'Linen\' THEN \'Linen\' ELSE \'Polyester\' END AS material FROM SNITCH_DB.MAPLEMONK.metafields_data ), offline_inv AS ( SELECT s.zone, UPPER(o.sku_group) AS sku_group, SUM(o.inventory) + SUM(o.jit_qty) AS offline_inventory FROM snitch_db.maplemonk.offline_master o JOIN ( SELECT DISTINCT branch_code, zone FROM snitch_db.maplemonk.store_category_delta ) s ON o.branch_code = s.branch_code GROUP BY 1, 2 ) SELECT a.warehouse_location, a.sku_group, COALESCE(a.product_name, m.product_name) AS product_name, a.category, a.sellable_inventory, COALESCE(off.offline_inventory, 0) AS offline_inventory, m.designs_new AS designs, m.collar_new_modified AS collar_new, m.fit, m.style, m.material, CASE WHEN UPPER(a.sku_group) IN ( SELECT DISTINCT UPPER(\"SKU Group\") FROM snitch_db.maplemonk.final_discount_skus_sheet1 WHERE category NOT IN (\'Collection\',\'Online NOOS\') ) THEN \'EOSS\' WHEN UPPER(a.sku_group) IN ( SELECT DISTINCT UPPER(\"SKU Group\") FROM snitch_db.maplemonk.final_discount_skus_sheet1 WHERE category IN (\'Collection\')) THEN \'Collection\' ELSE \'Fresh\' END AS allocation_status, m.sleeve_length, a.live_date, pi.image_url AS image_link, CASE WHEN UPPER(a.sku_group) LIKE \'%4MBG%\' OR UPPER(a.sku_group) LIKE \'%4BRN%\' OR UPPER(a.sku_group) LIKE \'%4BPL%\' OR UPPER(a.sku_group) LIKE \'%4BTR%\' OR UPPER(a.sku_group) LIKE \'%4BCH%\' OR UPPER(a.sku_group) LIKE \'%4BJE%\' OR UPPER(a.sku_group) LIKE \'%4BJK%\' OR UPPER(a.sku_group) LIKE \'%4BSW%\' OR UPPER(a.sku_group) LIKE \'%4BHD%\' OR UPPER(a.sku_group) LIKE \'%4BOS%\' OR UPPER(a.sku_group) LIKE \'%4BSHS%\' OR UPPER(a.sku_group) LIKE \'%4BSFS%\' OR UPPER(a.sku_group) LIKE \'%4BSH%\' OR UPPER(a.sku_group) LIKE \'%4BBL%\' OR UPPER(a.sku_group) LIKE \'%4BCA%\' OR UPPER(a.sku_group) LIKE \'%4BSWT%\' OR UPPER(a.sku_group) LIKE \'%4BCD%\' OR UPPER(a.sku_group) LIKE \'%4BJO%\' THEN GREATEST(LEAST( ROUND((a.XL3_UNITS - 1) / 3), ROUND((a.XL4_UNITS - 1) / 3), ROUND((a.XL5_UNITS - 1) / 2), ROUND((a.XL6_UNITS - 1) / 2) ), 0) WHEN UPPER(a.category) LIKE \'%JEANS%\' AND COALESCE(m.style, \'Snitch\') <> \'Plus\' THEN CASE WHEN GREATEST(LEAST( ROUND((a.s_units - 1) / 3), ROUND((a.m_units - 1) / 4), ROUND((a.l_units - 1) / 4), ROUND((a.xl_units - 1) / 3) ), 0) > 0 THEN GREATEST(LEAST( ROUND((a.s_units - 1) / 3), ROUND((a.m_units - 1) / 4), ROUND((a.l_units - 1) / 4), ROUND((a.xl_units - 1) / 3) ), 0) ELSE GREATEST( LEAST( ROUND((a.xs_units - 1) / 2), ROUND((a.s_units - 1) / 3), ROUND((a.m_units - 1) / 4), ROUND((a.l_units - 1) / 4) ), LEAST( ROUND((a.s_units - 1) / 3), ROUND((a.m_units - 1) / 4), ROUND((a.l_units - 1) / 4), ROUND((a.xl_units - 1) / 3) ), LEAST( ROUND((a.m_units - 1) / 4), ROUND((a.l_units - 1) / 4), ROUND((a.xl_units - 1) / 3), ROUND((a.xxl_units - 1) / 2) ), 0 ) END ELSE GREATEST(LEAST( ROUND((a.s_units - 1) / 3), ROUND((a.m_units - 1) / 4), ROUND((a.l_units - 1) / 4), ROUND((a.xl_units - 1) / 3) ), 0) END AS full_size_options FROM SNITCH_DB.MAPLEMONK.availability_master_v2_merged a LEFT JOIN metafields_std m ON a.sku_group = m.sku_group LEFT JOIN product_images pi ON a.sku_group = pi.sku_group LEFT JOIN offline_inv off ON UPPER(a.warehouse_location) = UPPER(off.zone) AND UPPER(a.sku_group) = off.sku_group WHERE a.sellable_inventory > 0 AND a.sku_group NOT LIKE \'MP%\' AND a.sku_group NOT LIKE \'%_T\'; CREATE OR REPLACE TABLE snitch_db.maplemonk.off_master_htmlbase AS WITH opening AS ( SELECT date AS opening_date, cluster, branch_code, marketplace_mapped, UPPER(sku_group) AS sku_group, inventory AS opening_inventory, new_category, designs, collar_new, sleeve_type, fit, style, material_new FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE date = current_date - 30 ), closing AS ( SELECT current_date AS closing_date, cluster, branch_code, marketplace_mapped, UPPER(sku_group) AS sku_group, inventory AS closing_inventory, jit_qty, num_size_available, new_category, designs, XS_UNITS,S_UNITS,M_UNITS,L_UNITS,XL_UNITS,XXL_UNITS,XL3_UNITS,XL4_UNITS,XL5_UNITS,XL6_UNITS,JIT_XS_UNITS,JIT_S_UNITS,JIT_M_UNITS,JIT_L_UNITS,JIT_XL_UNITS,JIT_2XL_UNITS,JIT_3XL_UNITS,JIT_4XL_UNITS,JIT_5XL_UNITS,JIT_6XL_UNITS, CASE WHEN UPPER(SKU_GROUP) LIKE \'4MBG%\' OR UPPER(SKU_GROUP) LIKE \'4BRN%\' OR UPPER(SKU_GROUP) LIKE \'4BPL%\' OR UPPER(SKU_GROUP) LIKE \'4BTR%\' OR UPPER(SKU_GROUP) LIKE \'4BCH%\' OR UPPER(SKU_GROUP) LIKE \'4BJE%\' OR UPPER(SKU_GROUP) LIKE \'4BJK%\' OR UPPER(SKU_GROUP) LIKE \'4BSW%\' OR UPPER(SKU_GROUP) LIKE \'4BHD%\' OR UPPER(SKU_GROUP) LIKE \'4BOS%\' OR UPPER(SKU_GROUP) LIKE \'4BSHS%\' OR UPPER(SKU_GROUP) LIKE \'4BSFS%\' OR UPPER(SKU_GROUP) LIKE \'4BSH%\' OR UPPER(SKU_GROUP) LIKE \'4BBL%\' OR UPPER(SKU_GROUP) LIKE \'4BCA%\' OR UPPER(SKU_GROUP) LIKE \'4BSWT%\' OR UPPER(SKU_GROUP) LIKE \'4BCD%\' OR UPPER(SKU_GROUP) LIKE \'4BJO%\' THEN CASE WHEN ( (CASE WHEN XL3_UNITS + JIT_3XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL4_UNITS + JIT_4XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL5_UNITS + JIT_5XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL6_UNITS + JIT_6XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 3 THEN \'YES\' ELSE \'NO\' END ELSE CASE WHEN ( (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 3 OR ( (CASE WHEN XS_UNITS + JIT_XS_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XXL_UNITS + JIT_2XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 4 THEN \'YES\' ELSE \'NO\' END END AS cut_size, collar_new, sleeve_type, fit, style, material_new, sales_last_7_days, CASE WHEN fresh_inventory > 0 AND fresh_inventory = inventory THEN \'Fresh\' ELSE \'Old\' END AS fresh_remark FROM snitch_db.maplemonk.offline_master ), sales AS ( SELECT branch_code, marketplace_mapped, UPPER(sku_group) AS sku_group, SUM(suborder_quantity) AS sales_qty FROM snitch_db.maplemonk.store_fact_items_offline WHERE order_date BETWEEN current_date - 30 AND current_date AND marketplace_mapped NOT IN ( \'SNITCH - WH - EMIZA\',\'SNITCH - WH - SR\',\'SNITCH - WH - YELHANKA\',\'SNITCH - WH - YELHANKA 2\', \'SNITCH - MARKET PLACE - SLIKK\',\'SNITCH - WH - B2B\',\'SNITCH - WH - GUJARAT\',\'SNITCH - WH - M P\', \'SNITCH - WH - RAJASTHAN\',\'SNITCH - WH - U.P\',\'SNITCH - SNITCH X\',\'SNITCH - WH - NORTH\' ) AND doc_prefix NOT IN (\'QCOM\',\'OMS\') AND sku_group NOT LIKE \'%CB%\' GROUP BY branch_code, marketplace_mapped, UPPER(sku_group) ), sales_mtd AS ( SELECT branch_code, marketplace_mapped, UPPER(sku_group) AS sku_group, SUM(suborder_quantity) AS sales_qty_mtd FROM snitch_db.maplemonk.store_fact_items_offline WHERE order_date BETWEEN date_trunc(\'month\', current_date) AND current_date AND marketplace_mapped NOT IN ( \'SNITCH - WH - EMIZA\',\'SNITCH - WH - SR\',\'SNITCH - WH - YELHANKA\',\'SNITCH - WH - YELHANKA 2\', \'SNITCH - MARKET PLACE - SLIKK\',\'SNITCH - WH - B2B\',\'SNITCH - WH - GUJARAT\',\'SNITCH - WH - M P\', \'SNITCH - WH - RAJASTHAN\',\'SNITCH - WH - U.P\',\'SNITCH - SNITCH X\',\'SNITCH - WH - NORTH\' ) AND doc_prefix NOT IN (\'QCOM\',\'OMS\') AND sku_group NOT LIKE \'%CB%\' GROUP BY branch_code, marketplace_mapped, UPPER(sku_group) ), omni_sales_30 AS ( SELECT branch_code, marketplace_mapped, UPPER(sku_group) AS sku_group, SUM(suborder_quantity) AS omni_sales_qty FROM snitch_db.maplemonk.store_fact_items_offline WHERE order_date BETWEEN current_date - 30 AND current_date AND marketplace_mapped NOT IN ( \'SNITCH - WH - EMIZA\',\'SNITCH - WH - SR\',\'SNITCH - WH - YELHANKA\',\'SNITCH - WH - YELHANKA 2\', \'SNITCH - MARKET PLACE - SLIKK\',\'SNITCH - WH - B2B\',\'SNITCH - WH - GUJARAT\',\'SNITCH - WH - M P\', \'SNITCH - WH - RAJASTHAN\',\'SNITCH - WH - U.P\',\'SNITCH - SNITCH X\',\'SNITCH - WH - NORTH\' ) AND doc_prefix IN (\'OMS\') AND sku_group NOT LIKE \'%CB%\' GROUP BY branch_code, marketplace_mapped, UPPER(sku_group) ), omni_sales_mtd AS ( SELECT branch_code, marketplace_mapped, UPPER(sku_group) AS sku_group, SUM(suborder_quantity) AS omni_sales_qty_mtd FROM snitch_db.maplemonk.store_fact_items_offline WHERE order_date BETWEEN date_trunc(\'month\', current_date) AND current_date AND marketplace_mapped NOT IN ( \'SNITCH - WH - EMIZA\',\'SNITCH - WH - SR\',\'SNITCH - WH - YELHANKA\',\'SNITCH - WH - YELHANKA 2\', \'SNITCH - MARKET PLACE - SLIKK\',\'SNITCH - WH - B2B\',\'SNITCH - WH - GUJARAT\',\'SNITCH - WH - M P\', \'SNITCH - WH - RAJASTHAN\',\'SNITCH - WH - U.P\',\'SNITCH - SNITCH X\',\'SNITCH - WH - NORTH\' ) AND doc_prefix IN (\'OMS\') AND sku_group NOT LIKE \'%CB%\' GROUP BY branch_code, marketplace_mapped, UPPER(sku_group) ), base_stock AS ( SELECT branch_code, MAX(base_stock) AS base_stock FROM snitch_db.maplemonk.offline_master WHERE branch_code IS NOT NULL AND base_stock IS NOT NULL GROUP BY branch_code ), combined AS ( SELECT COALESCE(o.branch_code, c.branch_code, s.branch_code) AS branch_code, c.cluster AS cluster, COALESCE(c.marketplace_mapped, s.marketplace_mapped) AS marketplace_mapped, COALESCE(o.sku_group, c.sku_group, s.sku_group) AS sku_group, COALESCE(o.opening_inventory, 0) AS opening_inventory, COALESCE(c.closing_inventory, 0) AS closing_inventory, COALESCE(c.jit_qty, 0) AS jit_qty, COALESCE(c.num_size_available, 0) AS num_size_available, COALESCE(s.sales_qty, 0) AS sales_qty, COALESCE(smtd.sales_qty_mtd, 0) AS sales_qty_mtd, COALESCE(os30.omni_sales_qty, 0) AS omni_sales_qty, COALESCE(osmtd.omni_sales_qty_mtd, 0) AS omni_sales_qty_mtd, COALESCE(C.SALES_LAST_7_DAYS,0) as sales_qty_l7, CASE WHEN COALESCE(o.new_category, c.new_category) IS NOT NULL THEN COALESCE(o.new_category, c.new_category) WHEN COALESCE(o.sku_group, c.sku_group, s.sku_group) LIKE \'SN%\' THEN \'Sunglasses\' WHEN COALESCE(o.sku_group, c.sku_group, s.sku_group) LIKE \'4MSFR%\' THEN \'Perfumes\' ELSE \'Accessories\' END AS new_category, COALESCE(o.designs, c.designs) AS designs, COALESCE(o.collar_new, c.collar_new) AS collar_new, COALESCE(o.sleeve_type, c.sleeve_type) AS sleeve_type, COALESCE(o.fit, c.fit) AS fit, COALESCE(o.style, c.style) AS style, COALESCE(o.material_new, c.material_new) AS material_new, COALESCE(bs.base_stock, 0) AS base_stock, COALESCE(c.fresh_remark, \'Old\') AS fresh_old_remark, COALESCE(c.cut_size, \'NO\') AS cut_size, c.XS_UNITS, c.S_UNITS, c.M_UNITS, c.L_UNITS, c.XL_UNITS, c.XXL_UNITS, c.XL3_UNITS, c.XL4_UNITS, c.XL5_UNITS, c.XL6_UNITS, c.JIT_XS_UNITS, c.JIT_S_UNITS, c.JIT_M_UNITS, c.JIT_L_UNITS, c.JIT_XL_UNITS, c.JIT_2XL_UNITS, c.JIT_3XL_UNITS, c.JIT_4XL_UNITS, c.JIT_5XL_UNITS, c.JIT_6XL_UNITS FROM opening o FULL OUTER JOIN closing c ON o.branch_code = c.branch_code AND o.sku_group = c.sku_group FULL OUTER JOIN sales s ON COALESCE(o.branch_code, c.branch_code) = s.branch_code AND COALESCE(o.sku_group, c.sku_group) = s.sku_group LEFT JOIN sales_mtd smtd ON COALESCE(o.branch_code, c.branch_code, s.branch_code) = smtd.branch_code AND COALESCE(o.sku_group, c.sku_group, s.sku_group) = smtd.sku_group LEFT JOIN omni_sales_30 os30 ON COALESCE(o.branch_code, c.branch_code, s.branch_code) = os30.branch_code AND COALESCE(o.sku_group, c.sku_group, s.sku_group) = os30.sku_group LEFT JOIN omni_sales_mtd osmtd ON COALESCE(o.branch_code, c.branch_code, s.branch_code) = osmtd.branch_code AND COALESCE(o.sku_group, c.sku_group, s.sku_group) = osmtd.sku_group LEFT JOIN base_stock bs ON COALESCE(o.branch_code, c.branch_code, s.branch_code) = bs.branch_code ), filtered AS ( SELECT *, CASE WHEN cut_size = \'NO\' THEN \'Full Size\' ELSE \'Cut Size\' END AS size_category FROM combined WHERE NOT (opening_inventory = 0 AND closing_inventory = 0 AND sales_qty = 0 and jit_qty=0) ), sku_store AS ( SELECT f.*, CASE WHEN (opening_inventory + closing_inventory) > 0 THEN ROUND(sales_qty / ((opening_inventory + closing_inventory) / 2.0), 2) ELSE 0 END AS sell_through_1, SUM(sales_qty) OVER (PARTITION BY cluster, sku_group) AS cluster_sales_qty, SUM(opening_inventory) OVER (PARTITION BY cluster, sku_group) AS cluster_opening_inventory, SUM(closing_inventory) OVER (PARTITION BY cluster, sku_group) AS cluster_closing_inventory, CASE WHEN ( SUM(opening_inventory) OVER (PARTITION BY cluster, sku_group) + SUM(closing_inventory) OVER (PARTITION BY cluster, sku_group) ) > 0 THEN ROUND( SUM(sales_qty) OVER (PARTITION BY cluster, sku_group) / ( ( SUM(opening_inventory) OVER (PARTITION BY cluster, sku_group) + SUM(closing_inventory) OVER (PARTITION BY cluster, sku_group) ) / 2.0 ), 2 ) ELSE 0 END AS cluster_sell_through_1, CASE WHEN ( SUM(opening_inventory) OVER (PARTITION BY branch_code) + SUM(closing_inventory) OVER (PARTITION BY branch_code) ) > 0 THEN ROUND( SUM(sales_qty) OVER (PARTITION BY branch_code) / ( ( SUM(opening_inventory) OVER (PARTITION BY branch_code) + SUM(closing_inventory) OVER (PARTITION BY branch_code) ) / 2.0 ), 2 ) ELSE 0 END AS store_sell_through_1 FROM filtered f ), images AS ( select sku_group,image_url from snitch_db.maplemonk.base_product ), sku_mrp AS ( SELECT CASE WHEN UPPER(\"Item SkuCode\") LIKE \'4C-%\' THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 3) WHEN POSITION(\'-\' IN \"Item SkuCode\") > 0 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) ELSE \"Item SkuCode\" END AS sku_group, MAX(mrp) AS mrp FROM snitch_db.maplemonk.unicommerce_live_inventory GROUP BY 1 ), sku_colour AS ( SELECT UPPER(sku_group) AS sku_group, CASE WHEN UPPER(TRIM(color)) IN (\'BLACK\') THEN \'Black\' WHEN UPPER(TRIM(color)) IN (\'ASH GREY\',\'CHARCOAL GREY\',\'DARK GREY\',\'GRAY\',\'GREY\',\'GREYISH BLU\',\'LIGHT GREY\') THEN \'Grey\' WHEN UPPER(TRIM(color)) IN (\'BEIGE\',\'CREAM\',\'IVORY\',\'LIGHT BEIGE\') THEN \'Beige\' WHEN UPPER(TRIM(color)) IN (\'BLUE\',\'BLUE GREY\',\'LIGHT BLUE\',\'SKY BLUE\',\'TEAL\',\'TEAL BLUE\',\'TURQUOISE\') THEN \'Blue\' WHEN UPPER(TRIM(color)) IN (\'DARK BLUE\',\'INDIGO\',\'NAVY\',\'NAVY BLUE\') THEN \'Navy\' WHEN UPPER(TRIM(color)) IN (\'BROWN\',\'DARK BROW\',\'HAZELNUT\',\'LIGHT BROW\',\'TAN\') THEN \'Brown\' WHEN UPPER(TRIM(color)) IN (\'BURGUNDY\',\'MAGENTA\',\'MAROON\') THEN \'Maroon\' WHEN UPPER(TRIM(color)) IN (\'DARK GREE\',\'GREEN\',\'LIGHT GREEN\',\'LIME GREE\',\'MINT\',\'MINT GREEN\',\'SAGE\',\'SAGE GREEN\') THEN \'Green\' WHEN UPPER(TRIM(color)) IN (\'LAVENDER\',\'LILAC\',\'MAUVE\') THEN \'Lavender\' WHEN UPPER(TRIM(color)) IN (\'LIGHT PINK\',\'PEACH\',\'PINK\') THEN \'Pink\' WHEN UPPER(TRIM(color)) IN (\'MULTI\',\'MULTICOLOR\',\'MULTICOLOUR\') THEN \'Multi\' WHEN UPPER(TRIM(color)) IN (\'MUSTARD\',\'YELLOW\') THEN \'Yellow\' WHEN UPPER(TRIM(color)) IN (\'NUDE\',\'WHITE\') THEN \'White\' WHEN UPPER(TRIM(color)) IN (\'OFF WHITE\',\'OFF-WHITE\') THEN \'Off-White\' WHEN UPPER(TRIM(color)) IN (\'OLIVE\',\'OLIVE GREEN\') THEN \'Olive\' WHEN UPPER(TRIM(color)) IN (\'ORANGE\',\'RUST ORANGE\') THEN \'Orange\' WHEN UPPER(TRIM(color)) IN (\'PURPLE\',\'VIOLET\',\'WINE\') THEN \'Purple\' WHEN UPPER(TRIM(color)) IN (\'RED\',\'RUST\') THEN \'Red\' WHEN UPPER(TRIM(color)) IN (\'SILVER\',\'STAINLESS STEEL\') THEN \'Silver\' WHEN UPPER(TRIM(color)) = \'GOLD\' THEN \'Gold\' WHEN UPPER(TRIM(color)) = \'KHAKI\' THEN \'Khaki\' ELSE \'Others\' END AS colour FROM snitch_db.maplemonk.metafields_data ) SELECT ss.cluster AS state, SS.BRANCH_CODE, ss.marketplace_mapped, ss.new_category, ss.sku_group, pj.product_name, img.image_url AS image, ss.fit, CASE WHEN UPPER(ss.sku_group) LIKE \'%4MLX%\' OR UPPER(ss.sku_group) LIKE \'%4LRN%\' OR UPPER(ss.sku_group) LIKE \'%4LPL%\' OR UPPER(ss.sku_group) LIKE \'%4LTR%\' OR UPPER(ss.sku_group) LIKE \'%4LCH%\' OR UPPER(ss.sku_group) LIKE \'%4LJE%\' OR UPPER(ss.sku_group) LIKE \'%4LJK%\' OR UPPER(ss.sku_group) LIKE \'%4LSW%\' OR UPPER(ss.sku_group) LIKE \'%4LHD%\' OR UPPER(ss.sku_group) LIKE \'%4LOS%\' OR UPPER(ss.sku_group) LIKE \'%4LSHS%\' OR UPPER(ss.sku_group) LIKE \'%4LSFS%\' OR UPPER(ss.sku_group) LIKE \'%4LSH%\' OR UPPER(ss.sku_group) LIKE \'%4LBL%\' OR UPPER(ss.sku_group) LIKE \'%4LCA%\' OR UPPER(ss.sku_group) LIKE \'%4LSWT%\' OR UPPER(ss.sku_group) LIKE \'%4LCD%\' OR UPPER(ss.sku_group) LIKE \'%4LJO%\' THEN \'Luxe\' WHEN UPPER(ss.sku_group) LIKE \'%4MBG%\' OR UPPER(ss.sku_group) LIKE \'%4BRN%\' OR UPPER(ss.sku_group) LIKE \'%4BPL%\' OR UPPER(ss.sku_group) LIKE \'%4BTR%\' OR UPPER(ss.sku_group) LIKE \'%4BCH%\' OR UPPER(ss.sku_group) LIKE \'%4BJE%\' OR UPPER(ss.sku_group) LIKE \'%4BJK%\' OR UPPER(ss.sku_group) LIKE \'%4BSW%\' OR UPPER(ss.sku_group) LIKE \'%4BHD%\' OR UPPER(ss.sku_group) LIKE \'%4BOS%\' OR UPPER(ss.sku_group) LIKE \'%4BSHS%\' OR UPPER(ss.sku_group) LIKE \'%4BSFS%\' OR UPPER(ss.sku_group) LIKE \'%4BSH%\' OR UPPER(ss.sku_group) LIKE \'%4BBL%\' OR UPPER(ss.sku_group) LIKE \'%4BCA%\' OR UPPER(ss.sku_group) LIKE \'%4BSWT%\' OR UPPER(ss.sku_group) LIKE \'%4BCD%\' OR UPPER(ss.sku_group) LIKE \'%4BJO%\' THEN \'Plus\' ELSE \'Snitch\' END AS style, CASE WHEN LOWER(ss.STYLE) LIKE \'%linen%\' THEN \'Linen\' WHEN MATERIAL_NEW = \'Cotton\' THEN \'Cotton\' WHEN MATERIAL_NEW IN (\'Tencel\', \'Tencil\', \'Polyester\', \'Terry\', \'Rayon\', \'Nylon\', \'Modal\', \'Others\') THEN \'Polyester\' WHEN MATERIAL_NEW = \'Linen\' THEN \'Linen\' ELSE \'Polyester\' END AS MATERIAL, CASE WHEN TRIM(LOWER(ss.sleeve_type)) IN (\'sleeveless\') THEN \'Sleeveless\' WHEN TRIM(LOWER(ss.sleeve_type)) IN (\'half sleeve\',\'elbow sleeve\') THEN \'Half Sleeve\' WHEN TRIM(LOWER(ss.sleeve_type)) in (\'full sleeve\',\'three-quarter sleeves\') THEN \'Full Sleeve\' ELSE \'Others\' END as sleeve_length, ss.fresh_old_remark, ss.opening_inventory, ss.size_category, ss.base_stock, CASE WHEN ss.new_category = \'T-Shirts\' THEN CASE WHEN UPPER(TRIM(ss.designs)) = \'SOLID\' THEN \'Solid\' WHEN UPPER(TRIM(ss.designs)) IN (\'GRAPHIC PRINT\',\'PRINTED\',\'GEOMETRIC\',\'FLORAL\',\'TIE & DYE\',\'ANIMAL PRINT\') THEN \'Graphic Print\' WHEN UPPER(TRIM(ss.designs)) IN (\'TEXTURED\',\'SELF DESIGN\') THEN \'Textured\' WHEN UPPER(TRIM(ss.designs)) = \'STRIPES\' THEN \'Stripes\' WHEN UPPER(TRIM(ss.designs)) IN (\'EMBROIDED\',\'EMBELLISHED\') THEN \'Embroidered\' WHEN UPPER(TRIM(ss.designs)) = \'CHECKS\' THEN \'Checks\' ELSE \'Others\' END WHEN ss.new_category = \'Shirts\' THEN CASE WHEN UPPER(TRIM(ss.designs)) = \'SOLID\' THEN \'Solid\' WHEN UPPER(TRIM(ss.designs)) = \'STRIPES\' THEN \'Stripes\' WHEN UPPER(TRIM(ss.designs)) IN (\'TEXTURED\',\'SELF DESIGN\') THEN \'Textured\' WHEN UPPER(TRIM(ss.designs)) = \'CHECKS\' THEN \'Checks\' WHEN UPPER(TRIM(ss.designs)) IN (\'PRINTED\',\'FLORAL\',\'GEOMETRIC\',\'TIE & DYE\',\'GRAPHIC PRINT\',\'ANIMAL PRINT\') THEN \'Printed\' WHEN UPPER(TRIM(ss.designs)) IN (\'EMBROIDED\',\'EMBELLISHED\') THEN \'Embroidered\' ELSE \'Others\' END ELSE ss.designs END AS designs_mapped, CASE WHEN ss.new_category = \'T-Shirts\' THEN CASE WHEN TRIM(LOWER(ss.collar_new)) IN (\'mock\',\'spread\',\'cuban\',\'mandarin\',\'baseball\',\'high neck\',\'zip\',\'others\') THEN \'Others\' WHEN TRIM(LOWER(ss.collar_new)) IN (\'v neck\',\'crew\',\'round\') THEN \'Round\' WHEN TRIM(LOWER(ss.collar_new)) = \'polo\' THEN \'Polo\' ELSE ss.collar_new END ELSE ss.collar_new END AS collar_new_mapped, mrp.mrp, col.colour, ss.sales_qty AS sales_last_30_days, ss.sales_qty_mtd AS sales_mtd, ss.omni_sales_qty AS omni_sales_last_30_days, ss.omni_sales_qty_mtd AS omni_sales_mtd, ss.sales_qty_l7 as sales_last_7_days, ss.closing_inventory AS inventory, ss.jit_qty, ss.num_size_available, ss.XS_UNITS, ss.S_UNITS, ss.M_UNITS, ss.L_UNITS, ss.XL_UNITS, ss.XXL_UNITS, ss.XL3_UNITS, ss.XL4_UNITS, ss.XL5_UNITS, ss.XL6_UNITS, ss.JIT_XS_UNITS, ss.JIT_S_UNITS, ss.JIT_M_UNITS, ss.JIT_L_UNITS, ss.JIT_XL_UNITS, ss.JIT_2XL_UNITS, ss.JIT_3XL_UNITS, ss.JIT_4XL_UNITS, ss.JIT_5XL_UNITS, ss.JIT_6XL_UNITS, ROUND(ss.sell_through_1 * 100, 0) AS str_pct, ROUND(ss.cluster_sell_through_1 * 100, 0) AS cluster_str_pct, CASE WHEN ss.sales_qty = 0 AND ss.closing_inventory > 8 AND ss.num_size_available >= 4 THEN \'0 STR\' WHEN ss.sell_through_1 >= ss.store_sell_through_1 THEN \'Top Selling\' WHEN ss.sell_through_1 < ss.store_sell_through_1 AND ss.size_category = \'Full Size\' AND ss.closing_inventory > 0 THEN \'Low Selling\' ELSE \'Others\' END AS sales_status, case when ss.jit_qty = 0 and ss.closing_inventory > 0 then \'At Store\' when ss.sales_qty = 0 and ss.closing_inventory = 0 and ss.jit_qty > 0 then \'Fresh in Transit\' when ss.sales_qty > 0 and ss.jit_qty > 0 then \'RPL in Transit\' when ss.sales_qty = 0 and ss.closing_inventory > 0 and ss.jit_qty > 0 then \'Stocked+Inbound\' when ss.closing_inventory=0 and ss.jit_qty= 0 then \'Stocked-Out\' else \'Others\' end as in_transit_status, FROM sku_store ss LEFT JOIN snitch_db.maplemonk.product_journey pj ON ss.sku_group = UPPER(pj.sku_group) LEFT JOIN images img ON ss.sku_group = img.sku_group LEFT JOIN sku_mrp mrp ON ss.sku_group = UPPER(mrp.sku_group) LEFT JOIN sku_colour col ON ss.sku_group = col.sku_group WHERE ss.cluster IS NOT NULL and ss.sku_group not like \'PP%\' AND SS.SKU_GROUP NOT LIKE \'NT%\' AND SS.SKU_GROUP NOT LIKE \'GIFT%\' AND SS.SKU_GROUP NOT LIKE \'MP%\' ORDER BY ss.cluster, ss.sales_qty DESC; create or replace table snitch_db.maplemonk.b2b_jour_htmlbase as WITH b2b AS ( SELECT state, final_store, final_status, CASE WHEN POSITION(\'-\' IN sku) > 0 THEN REVERSE(SUBSTR(REVERSE(sku), POSITION(\'-\' IN REVERSE(sku)) + 1)) ELSE sku END AS sku_group, CASE WHEN POSITION(\'-\' IN sku) > 0 THEN REVERSE(SPLIT_PART(REVERSE(sku), \'-\', 1)) ELSE NULL END AS size, qty, order_date, order_name, type, TRY_TO_DATE(NULLIF(TRIM(LOGISTICS_EXPECTED_DELIVERY_DATE), \'\')) AS EDD_original FROM snitch_db.maplemonk.b2b_journey WHERE final_status NOT IN (\'INWARDED\',\'INWARD_PENDING\') AND type NOT IN (\'QCOMM\',\'Qcomm\',\'OTHER\',\'QCOM\') ), meta AS ( SELECT sku_group, product_name, category, designs, collar_new, fit FROM snitch_db.maplemonk.metafields_data WHERE category IS NOT NULL ), pj AS ( SELECT sku_group, image FROM snitch_db.maplemonk.product_journey ), fp AS ( SELECT branch_name_priority, TRY_TO_NUMBER(NULLIF(TRIM(lead_time), \'\')) AS lead_time FROM snitch_db.maplemonk.google_sheet_fresh_priority ) SELECT b2b.state, b2b.final_store, b2b.final_status, b2b.sku_group, b2b.size, b2b.qty, b2b.order_date, b2b.order_name, b2b.type, COALESCE( b2b.EDD_original, DATEADD(\'day\', fp.lead_time, b2b.order_date) ) AS EDD, meta.product_name, meta.category, meta.designs, meta.collar_new, meta.fit, pj.image, fp.lead_time FROM b2b LEFT JOIN meta ON b2b.sku_group = meta.sku_group LEFT JOIN pj ON b2b.sku_group = pj.sku_group LEFT JOIN fp ON b2b.final_store = fp.branch_name_priority; create or replace table snitch_db.maplemonk.offline_git_summary as WITH dist_edd AS ( SELECT order_name, MAX(TO_DATE(delivery_tat)) AS mapped_edd, MAX(TO_DATE(ideal_delivery_date)) AS ideal_edd FROM snitch_db.maplemonk.distribution_analytics GROUP BY 1 ), b2b_base AS ( SELECT bj.state, bj.final_store, bj.final_status, CASE WHEN bj.warehouse_name IN (\'SAPL-NORTH-TAURU\') THEN \'SAPL-NORTH-TAURU\' ELSE \'SOUTH\' END AS warehouse_name, bj.order_date, bj.new_bill_no AS doc_no, bj.courier_partner, bj.tracking_number AS awb_number, bj.tracking_sub_status AS current_status, bj.tracking_latest_message AS current_scan, bj.order_name, bj.type, CASE WHEN UPPER(bj.sku) LIKE \'4C%\' THEN SPLIT_PART(bj.sku, \'-\', 1) || \'-\' || SPLIT_PART(bj.sku, \'-\', 2) || \'-\' || SPLIT_PART(bj.sku, \'-\', 3) WHEN POSITION(\'-\' IN bj.sku) > 0 THEN SPLIT_PART(bj.sku, \'-\', 1) || \'-\' || SPLIT_PART(bj.sku, \'-\', 2) ELSE bj.sku END AS sku_group, bj.qty, de.mapped_edd, de.ideal_edd FROM snitch_db.maplemonk.b2b_journey bj LEFT JOIN dist_edd de ON bj.order_name = de.order_name WHERE bj.final_status NOT IN (\'INWARDED\',\'INWARD_PENDING\') AND bj.type NOT IN (\'QCOMM\',\'Qcomm\',\'OTHER\') AND bj.final_store IS NOT NULL ), b2b AS ( SELECT state, final_store, final_status, warehouse_name, order_date, doc_no, courier_partner, awb_number, current_status, current_scan, LISTAGG(DISTINCT order_name, \',\') WITHIN GROUP (ORDER BY order_name) AS order_names, type, sku_group, SUM(qty) AS qty, MAX(mapped_edd) AS mapped_edd, max(ideal_edd) as ideal_edd FROM b2b_base GROUP BY state, final_store, final_status, warehouse_name, order_date, doc_no, courier_partner, awb_number, current_status, current_scan, type, sku_group ), meta AS ( SELECT DISTINCT sku_group, product_name, category, designs, collar_new, style, fit, material FROM snitch_db.maplemonk.av_master_htmbase WHERE category IS NOT NULL ), pj AS ( SELECT sku_group, image FROM snitch_db.maplemonk.product_journey ), south_rule AS ( SELECT \"STORE NAME\" AS store_name, UPPER(TRIM(\"Fresh Order Day\")) AS fresh_order_day, UPPER(TRIM(\"RPL Order Day\")) AS rpl_order_day, UPPER(TRIM(\"Fresh Delivery Day\")) AS fresh_delivery_day, UPPER(TRIM(\"RPL Delivery Day\")) AS rpl_delivery_day, TRY_TO_NUMBER(\"Best TAT\") AS best_tat FROM snitch_db.maplemonk.final_southrulebook ), north_rule AS ( SELECT \"STORE NAME\" AS store_name, UPPER(TRIM(\"Fresh Order Day\")) AS fresh_order_day, UPPER(TRIM(\"RPL Order Day\")) AS rpl_order_day, UPPER(TRIM(\"Fresh Delivery Day\")) AS fresh_delivery_day, UPPER(TRIM(\"RPL Delivery Day\")) AS rpl_delivery_day, TRY_TO_NUMBER(\"Best TAT\") AS best_tat FROM snitch_db.maplemonk.north_rule_merch ), base AS ( SELECT b2b.state, b2b.final_store, b2b.order_names, b2b.order_date, b2b.warehouse_name, b2b.sku_group, b2b.qty, b2b.type, b2b.final_status, b2b.courier_partner, b2b.doc_no, b2b.awb_number, b2b.current_status, b2b.current_scan, b2b.mapped_edd, b2b.ideal_edd, meta.product_name, meta.category, meta.designs, meta.collar_new, meta.fit, meta.style, meta.material FROM b2b LEFT JOIN meta ON b2b.sku_group = meta.sku_group LEFT JOIN south_rule sr ON b2b.final_store = sr.store_name LEFT JOIN north_rule nr ON b2b.final_store = nr.store_name ) SELECT state, final_store, order_names, order_date, warehouse_name, sku_group, qty, type, final_status, courier_partner, doc_no, awb_number, current_status, current_scan, COALESCE(mapped_edd, ideal_edd) AS edd, product_name, category, designs, collar_new, fit, style, material FROM base where order_names not like \'QC%\' ORDER BY final_store, order_names, sku_group, type;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            